  // data/shogi.js — 将棋のカリキュラム
  // 方針: 駒を1枚ずつ。成りと持ち駒は独立した章で扱う（ここが最大の壁）。
  // 3×4のミニ将棋で「持ち駒つきの完結した1局」を早めに体験させる。


  // ── 型の総復習用：左右反転（筋 f → 10−f）した問題も作り、決まった順に混ぜる
  const mirrorShogi = (b) => Object.fromEntries(Object.entries(b).map(([sq, p]) => [`${10 - Number(sq[0])}${sq[1]}`, p]));
  function drill(list) {
    const steps = list.map(([board, hand, name], i) => {
      const b = i % 2 ? mirrorShogi(board) : board;
      // 自玉（9九）は反転すると1九になる。どちらでも詰みには関係しない位置
      return {
        type: 'move', shape: BIG, goal: 'mate',
        state: { board: { ...b, [i % 2 ? '19' : '99']: 'K' }, hands: { b: { ...hand }, w: {} }, turn: 'b' },
        prompt: '1手で詰ませてください。',
        hint: '玉の逃げ道を数えてから、どの型に近いかを考えます。',
        why: `型は<strong>${name}</strong>でした。`,
      };
    });
    const order = [2, 5, 0, 4, 6, 1, 3];
    return order.filter((n) => n < steps.length).map((n) => steps[n]);
  }

  // ── 5手詰め。すべてエンジンで「5手で詰み・3手以内では詰まない・初手は1つだけ」を確かめてある
