// キング＋ポーンの終盤を、最善で守る相手から勝ちきる練習。開始局面はどれも、勝敗表で「白番・白の勝ち」を確かめてある。
const NS_DKPK = (() => {
  const { chess } = NS_DCHESS;
  const strong = chess.chapters.find((c) => c.title.includes('強くなるコース'));
  strong.lessons.push({
    id: 'chess.kpk-play', game: 'chess', title: 'キングとポーンで勝ちきる', desc: '最善で守る相手から、昇格まで',
    steps: [
      { type: 'teach', title: '実際に勝ちきる', body: '<p>前のレッスンの形から、最後まで指します。黒のキングは、すべての局面を計算した勝敗表を使って、いちばん粘る手で守ります。</p><p>1手でも間違えると引き分けの形になります。そのときは「1手もどす」でやり直せます。迷ったら「ヒント」で、勝ちにつながる手を確かめられます。</p>' },
      { type: 'kpkplay', board: { c4: 'K', e6: 'k', c5: 'P' }, prompt: '白番（1/3）。ポーンをクイーンに昇格させて勝ちきってください。黒は最善で守ります。' },
      { type: 'kpkplay', board: { c3: 'K', e5: 'k', c4: 'P' }, prompt: '白番（2/3）。少し手前からです。キングを先にポーンの前へ出しましょう。' },
      { type: 'kpkplay', board: { c2: 'K', e4: 'k', c3: 'P' }, prompt: '白番（3/3）。いちばん手前からです。対抗を取り続けて、昇格まで指してください。' },
    ],
  });
  return {};
})();

