  /** n路盤を作る。pts = [[x, y, 'X'|'O'|ラベル], ...]（x は左から、y は上から数える） */
  const Bn = (n, pts) => {
    const a = Array.from({ length: n }, () => Array(n).fill('.'));
    for (const [x, y, c] of pts) a[y - 1][x - 1] = c;
    return a.map((r) => r.join(''));
  };
  const B19 = (pts) => Bn(19, pts);
  const B13 = (pts) => Bn(13, pts);
  const B9 = (pts) => Bn(9, pts);

